#include <bits/stdc++.h>
using namespace std;

struct Item {
    string name;
    int q;
    long long v, m, l;
};

int n;
Item items[20];
long long bestVal;
int bestSol[20];
int curSol[20];
const long long capM = 20000000LL, capL = 25000000LL;
chrono::steady_clock::time_point startTime;
bool timeUp = false;

void checkTime() {
    auto now = chrono::steady_clock::now();
    if (chrono::duration_cast<chrono::milliseconds>(now - startTime).count() > 850)
        timeUp = true;
}

// LP relaxation upper bound using Dantzig-style for 2D knapsack
// We try multiple Lagrangian multipliers for tighter bound
double lpBound(int idx, long long rm, long long rl, long long curVal) {
    if (idx >= n) return (double)curVal;

    double best = 1e30;

    // Try several lambda values: combine as m_i + lambda * l_i <= rm + lambda * rl
    for (double lambda : {0.0, 0.01, 0.05, 0.1, 0.2, 0.5, 1.0, 2.0, 5.0, 10.0, 50.0, 100.0, 1000.0}) {
        double cap = (double)rm + lambda * (double)rl;

        // Build items with combined weight, sort by value/weight
        static pair<double, int> eff[20];
        int cnt = 0;
        for (int i = idx; i < n; i++) {
            double w = (double)items[i].m + lambda * (double)items[i].l;
            eff[cnt++] = {(w > 1e-15) ? (double)items[i].v / w : 1e30, i};
        }
        sort(eff, eff + cnt, [](auto& a, auto& b){ return a.first > b.first; });

        double ub = (double)curVal;
        double remCap = cap;

        for (int i = 0; i < cnt; i++) {
            int ii = eff[i].second;
            double w = (double)items[ii].m + lambda * (double)items[ii].l;
            double maxQ = (double)items[ii].q;
            // Also respect individual constraints
            if (items[ii].m > 0) maxQ = min(maxQ, (double)(rm / items[ii].m));  // but rm is shared... use relaxed
            if (items[ii].l > 0) maxQ = min(maxQ, (double)(rl / items[ii].l));

            double canByCap = (w > 1e-15) ? remCap / w : maxQ;
            double take = min(maxQ, canByCap);
            take = max(take, 0.0);

            if (take >= maxQ) {
                ub += (double)items[ii].v * maxQ;
                remCap -= w * maxQ;
            } else {
                ub += (double)items[ii].v * take;
                remCap = 0;
                break;
            }
        }
        best = min(best, ub);
    }
    return best;
}

long long nc = 0;

void solve(int idx, long long rm, long long rl, long long curVal) {
    if (timeUp) return;
    if (idx == n) {
        if (curVal > bestVal) {
            bestVal = curVal;
            memcpy(bestSol, curSol, sizeof(int) * n);
        }
        return;
    }

    if ((++nc & 0x3FFF) == 0) checkTime();
    if (timeUp) return;

    double ub = lpBound(idx, rm, rl, curVal);
    if (ub <= (double)bestVal + 0.5) return;

    long long maxByM = (items[idx].m > 0) ? rm / items[idx].m : (long long)items[idx].q;
    long long maxByL = (items[idx].l > 0) ? rl / items[idx].l : (long long)items[idx].q;
    int maxTake = (int)min({(long long)items[idx].q, maxByM, maxByL});

    for (int k = maxTake; k >= 0; k--) {
        curSol[idx] = k;
        solve(idx + 1, rm - (long long)k * items[idx].m, rl - (long long)k * items[idx].l, curVal + (long long)k * items[idx].v);
        if (timeUp) return;
    }
    curSol[idx] = 0;
}

int main(){
    startTime = chrono::steady_clock::now();
    string input((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());

    // Parse JSON: {"name": [q, v, m, l], ...}
    vector<pair<string, vector<long long>>> entries;
    size_t pos = 0;
    while ((pos = input.find('"', pos)) != string::npos) {
        size_t end = input.find('"', pos + 1);
        if (end == string::npos) break;
        string key = input.substr(pos + 1, end - pos - 1);
        pos = end + 1;
        size_t br = input.find('[', pos);
        if (br == string::npos) break;
        size_t br2 = input.find(']', br);
        if (br2 == string::npos) break;
        string arr = input.substr(br + 1, br2 - br - 1);
        pos = br2 + 1;
        vector<long long> nums;
        long long val = 0; bool inNum = false;
        for (char c : arr) {
            if (c >= '0' && c <= '9') { val = val * 10 + (c - '0'); inNum = true; }
            else { if (inNum) nums.push_back(val); val = 0; inNum = false; }
        }
        if (inNum) nums.push_back(val);
        if (nums.size() == 4) entries.push_back({key, nums});
    }

    n = entries.size();
    for (int i = 0; i < n; i++) {
        items[i].name = entries[i].first;
        items[i].q = (int)entries[i].second[0];
        items[i].v = entries[i].second[1];
        items[i].m = entries[i].second[2];
        items[i].l = entries[i].second[3];
    }

    // Sort by value density
    sort(items, items + n, [](const Item& a, const Item& b){
        double wa = max((double)a.m / capM, (double)a.l / capL);
        double wb = max((double)b.m / capM, (double)b.l / capL);
        double da = (wa > 1e-15) ? (double)a.v / wa : 1e30;
        double db = (wb > 1e-15) ? (double)b.v / wb : 1e30;
        return da > db;
    });

    bestVal = 0;
    memset(bestSol, 0, sizeof(bestSol));
    memset(curSol, 0, sizeof(curSol));

    solve(0, capM, capL, 0);

    cout << "{";
    for (int i = 0; i < n; i++) {
        if (i) cout << ", ";
        cout << "\"" << items[i].name << "\": " << bestSol[i];
    }
    cout << "}";

    return 0;
}
